Node* closest_node = nullptr;
float min_distance = std::numeric_limits<float>::max();
float current_distance;

// Iterate through all nodes in the graph
for (auto& node : m_nodes) {
    // Calculate Euclidean distance between given coordinates and current node
    current_distance = std::sqrt(std::pow(node.x - x, 2) + std::pow(node.y - y, 2));

    // Check if this node is closer than the current closest
    if (current_distance < min_distance) {
        // Check if this node belongs to any non-footway roads
        auto it = node_to_road.find(node.index_);
        if (it != node_to_road.end()) {
            bool is_valid = false;
            for (const auto& road : it->second) {
                if (road->type != Model::Road::Type::Footway) {
                    is_valid = true;
                    break;
                }
            }
            if (is_valid) {
                min_distance = current_distance;
                closest_node = &node;
            }
        }
    }
}

return closest_node;

